#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <stdatomic.h>

extern size_t aesni_gcm_encrypt(const unsigned char *in, unsigned char *out, size_t len,
                                const void *key, unsigned char ivec[16], void *Htable);
extern int aesni_set_encrypt_key(const unsigned char *userKey, int bits, void *key);
extern void aesni_encrypt(const unsigned char *in, unsigned char *out, const void *key);
extern void gcm_init_clmul(void *Htable, const void *H);
extern void gcm_ghash_avx(void *Xi, const void *Htable, const unsigned char *inp, size_t len);
extern void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
                                       size_t blocks, const void *key, const unsigned char ivec[16]);

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

#define N (60*1024*1024)

typedef struct {
    atomic_int sense;
    atomic_int count;
    int total;
} barrier_t;

static void barrier_init(barrier_t *b, int n) {
    atomic_store(&b->sense, 0);
    atomic_store(&b->count, 0);
    b->total = n;
}
static void barrier_wait(barrier_t *b) {
    int s = atomic_load(&b->sense);
    if (atomic_fetch_add(&b->count, 1) == b->total - 1) {
        atomic_store(&b->count, 0);
        atomic_store(&b->sense, s ^ 1);
    } else {
        while (atomic_load(&b->sense) == s) {
            /* spin */
        }
    }
}

typedef struct {
    unsigned char *in, *out;
    size_t off, len;
    unsigned char *key;
    unsigned char *htable;
    unsigned char iv[16];
    barrier_t *go, *done;
    atomic_int stop;
} job_t;

void *worker(void *arg) {
    job_t *j = arg;
    for (;;) {
        barrier_wait(j->go);
        if (atomic_load(&j->stop)) return NULL;
        aesni_gcm_encrypt(j->in + j->off, j->out + j->off, j->len, j->key, j->iv, j->htable);
        barrier_wait(j->done);
    }
}

int main() {
    unsigned char key[16];
    arc4random_buf(key, 16);
    unsigned char aeskey[256];
    aesni_set_encrypt_key(key, 128, aeskey);
    unsigned char H[16] = {0};
    unsigned char zero[16] = {0};
    aesni_encrypt(zero, H, aeskey);
    unsigned char htable[4096];
    gcm_init_clmul(htable, H);

    unsigned char *in = aligned_alloc(64, N);
    unsigned char *out = aligned_alloc(64, N);
    arc4random_buf(in, N);
    unsigned char nonce[12];
    arc4random_buf(nonce, 12);
    unsigned char iv[16];

    int iters = 5;
    double t0 = now();
    for (int i = 0; i < iters; i++) {
        memcpy(iv, nonce, 12); iv[12]=0; iv[13]=0; iv[14]=0; iv[15]=2;
        aesni_gcm_encrypt(in, out, N, aeskey, iv, htable);
    }
    double t1 = now();
    printf("single: %.2f ms  %.0f MB/s\n", (t1-t0)/iters*1000, (N/1e6)/((t1-t0)/iters));

    t0 = now();
    for (int i = 0; i < iters; i++) {
        memcpy(iv, nonce, 12); iv[12]=0; iv[13]=0; iv[14]=0; iv[15]=2;
        aesni_ctr32_encrypt_blocks(in, out, N/16, aeskey, iv);
    }
    t1 = now();
    printf("ctr32:  %.2f ms  %.0f MB/s\n", (t1-t0)/iters*1000, (N/1e6)/((t1-t0)/iters));

    unsigned char Xi[16];
    t0 = now();
    for (int i = 0; i < iters; i++) {
        memset(Xi, 0, 16);
        gcm_ghash_avx(Xi, htable, out, N);
    }
    t1 = now();
    printf("ghash:  %.2f ms  %.0f MB/s\n", (t1-t0)/iters*1000, (N/1e6)/((t1-t0)/iters));

    for (int nt = 2; nt <= 6; nt++) {
        barrier_t go, done;
        barrier_init(&go, nt+1);
        barrier_init(&done, nt+1);
        job_t jobs[8];
        pthread_t th[8];
        size_t chunk = (N / nt) & ~15ULL;
        static unsigned char htables[8][4096];
        for (int i = 0; i < nt; i++) {
            memcpy(htables[i], htable, 4096);
            size_t off = (size_t)i * chunk;
            size_t len = (i == nt-1) ? N - off : chunk;
            jobs[i].in = in; jobs[i].out = out;
            jobs[i].off = off; jobs[i].len = len;
            jobs[i].key = aeskey; jobs[i].htable = htables[i];
            memcpy(jobs[i].iv, nonce, 12);
            uint32_t ctr = 2 + (uint32_t)(off / 16);
            jobs[i].iv[12] = ctr >> 24; jobs[i].iv[13] = ctr >> 16;
            jobs[i].iv[14] = ctr >> 8; jobs[i].iv[15] = ctr;
            jobs[i].go = &go; jobs[i].done = &done;
            atomic_store(&jobs[i].stop, 0);
            pthread_create(&th[i], NULL, worker, &jobs[i]);
        }
        barrier_wait(&go); barrier_wait(&done);
        t0 = now();
        for (int k = 0; k < iters; k++) {
            barrier_wait(&go); barrier_wait(&done);
        }
        t1 = now();
        printf("nt=%d:   %.2f ms  %.0f MB/s\n", nt, (t1-t0)/iters*1000, (N/1e6)/((t1-t0)/iters));
        for (int i = 0; i < nt; i++) atomic_store(&jobs[i].stop, 1);
        barrier_wait(&go);
        for (int i = 0; i < nt; i++) pthread_join(th[i], NULL);
    }
    return 0;
}
