{"command":"cat > ./aesgcm_fast.c << 'EOF'
/* Fast AES-GCM using OpenSSL AES-NI assembly + parallel CTR/GHASH.
 * Build: cc -O3 -shared -fPIC -o aesgcm_fast.so aesgcm_fast.c -L/usr/local/lib -lcrypto -lpthread
 */
#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

extern int aesni_set_encrypt_key(const unsigned char *userKey, int bits, void *key);
extern void aesni_encrypt(const unsigned char *in, unsigned char *out, const void *key);
extern void gcm_init_avx(void *Htable, const void *H);
extern void gcm_init_clmul(void *Htable, const void *H);
extern void gcm_ghash_avx(void *Xi, const void *Htable, const unsigned char *inp, size_t len);
extern void gcm_gmult_clmul(void *Xi, const void *Htable);
extern void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
                                       size_t blocks, const void *key, const unsigned char ivec[16]);

static void bswap64_16(const unsigned char in[16], unsigned char out[16]) {
    for (int i = 0; i < 8; i++) {
        out[i] = in[7 - i];
        out[8 + i] = in[15 - i];
    }
}

/* X *= Y  (both in GHASH byte order, i.e. H.raw form). table is 1024 scratch. */
static void mul(unsigned char X[16], const unsigned char Y[16], unsigned char *table) {
    unsigned char Ys[16];
    bswap64_16(Y, Ys);
    gcm_init_clmul(table, Ys);
    gcm_gmult_clmul(X, table);
}

static void xor16(unsigned char *d, const unsigned char *s) {
    for (int i = 0; i < 16; i++) d[i] ^= s[i];
}

#define MAX_POW 40
#define MAX_THREADS 8

typedef struct {
    const unsigned char *in;
    unsigned char *out;
    size_t blocks;
    size_t off_blocks;
    const unsigned char *aeskey;
    unsigned char *htable;
    unsigned char iv[16];
    unsigned char xi[16];
    pthread_mutex_t *mtx;
    pthread_cond_t *cv;
    int *phase;          /* 0 idle, 1 work, 2 exit */
    int *remaining;
    int id;
} worker_t;

static void *worker_main(void *arg) {
    worker_t *w = arg;
    int seen = 0;
    for (;;) {
        pthread_mutex_lock(w->mtx);
        while (*w->phase == seen) pthread_cond_wait(w->cv, w->mtx);
        seen = *w->phase;
        int phase = *w->phase;
        pthread_mutex_unlock(w->mtx);
        if (phase == 2) break;
        if (w->blocks) {
            aesni_ctr32_encrypt_blocks(w->in + w->off_blocks * 16,
                                       w->out + w->off_blocks * 16,
                                       w->blocks, w->aeskey, w->iv);
            memset(w->xi, 0, 16);
            gcm_ghash_avx(w->xi, w->htable, w->out + w->off_blocks * 16, w->blocks * 16);
        }
        pthread_mutex_lock(w->mtx);
        if (--*w->remaining == 0) pthread_cond_signal(w->cv);
        pthread_mutex_unlock(w->mtx);
    }
    return NULL;
}

typedef struct {
    int nthreads;
    pthread_t th[MAX_THREADS];
    worker_t w[MAX_THREADS];
    pthread_mutex_t mtx;
    pthread_cond_t cv;
    int phase;
    int remaining;
    unsigned char htables[MAX_THREADS][8192];
    int inited;
} pool_t;

static pool_t g_pool;

static void pool_init(int nt) {
    if (g_pool.inited) return;
    if (nt < 1) nt = 1;
    if (nt > MAX_THREADS) nt = MAX_THREADS;
    g_pool.nthreads = nt;
    pthread_mutex_init(&g_pool.mtx, NULL);
    pthread_cond_init(&g_pool.cv, NULL);
    g_pool.phase = 0;
    for (int i = 0; i < nt; i++) {
        worker_t *w = &g_pool.w[i];
        w->mtx = &g_pool.mtx;
        w->cv = &g_pool.cv;
        w->phase = &g_pool.phase;
        w->remaining = &g_pool.remaining;
        w->htable = g_pool.htables[i];
        w->id = i;
        pthread_create(&g_pool.th[i], NULL, worker_main, w);
    }
    g_pool.inited = 1;
}

/* Encrypt and return tag. out must hold len bytes. tag 16 bytes.
 * nonce_len 12 only for the fast counter path; other lengths handled in Python? We'll support any.
 * For simplicity this function requires 12-byte nonce. Python handles other cases or we do too.
 */
int aesgcm_encrypt(const unsigned char *key, int key_bits,
                   const unsigned char *nonce, size_t nonce_len,
                   const unsigned char *aad, size_t aad_len,
                   const unsigned char *pt, size_t pt_len,
                   unsigned char *out, unsigned char tag[16],
                   int nthreads) {
    unsigned char aeskey[256];
    if (aesni_set_encrypt_key(key, key_bits, aeskey) != 0) return -1;

    unsigned char H[16], zero[16] = {0};
    aesni_encrypt(zero, H, aeskey);

    unsigned char Hs[16];
    bswap64_16(H, Hs);

    unsigned char htable[8192];
    gcm_init_avx(htable, Hs);

    /* J0 */
    unsigned char J0[16];
    if (nonce_len == 12) {
        memcpy(J0, nonce, 12);
        J0[12] = 0; J0[13] = 0; J0[14] = 0; J0[15] = 1;
    } else {
        memset(J0, 0, 16);
        size_t n = nonce_len & ~15ULL;
        if (n) gcm_ghash_avx(J0, htable, nonce, n);
        if (nonce_len & 15) {
            unsigned char blk[16] = {0};
            memcpy(blk, nonce + n, nonce_len - n);
            gcm_ghash_avx(J0, htable, blk, 16);
        }
        unsigned char lens[16] = {0};
        uint64_t bits = (uint64_t)nonce_len * 8;
        for (int i = 0; i < 8; i++) lens[15 - i] = (unsigned char)(bits >> (8 * i));
        gcm_ghash_avx(J0, htable, lens, 16);
    }

    size_t blocks = pt_len / 16;
    size_t rem = pt_len - blocks * 16;

    int nt = nthreads;
    if (nt < 1) nt = 1;
    if (blocks < 8192) nt = 1;
    if (nt > MAX_THREADS) nt = MAX_THREADS;
    if (nt > 1) pool_init(nt);

    if (nt == 1) {
        if (blocks) {
            unsigned char iv[16];
            memcpy(iv, J0, 12);
            uint32_t ctr = ((uint32_t)J0[12] << 24) | ((uint32_t)J0[13] << 16) |
                           ((uint32_t)J0[14] << 8) | J0[15];
            ctr += 1;
            iv[12] = ctr >> 24; iv[13] = ctr >> 16; iv[14] = ctr >> 8; iv[15] = ctr;
            aesni_ctr32_encrypt_blocks(pt, out, blocks, aeskey, iv);
        }
    } else {
        /* copy htable to workers (read-only, but keep separate) */
        uint32_t ctr0 = ((uint32_t)J0[12] << 24) | ((uint32_t)J0[13] << 16) |
                        ((uint32_t)J0[14] << 8) | J0[15];
        size_t chunk = blocks / nt;
        pthread_mutex_lock(&g_pool.mtx);
        g_pool.remaining = nt;
        for (int i = 0; i < nt; i++) {
            size_t off = (size_t)i * chunk;
            size_t n = (i == nt - 1) ? blocks - off : chunk;
            worker_t *w = &g_pool.w[i];
            w->in = pt; w->out = out;
            w->blocks = n; w->off_blocks = off;
            w->aeskey = aeskey;
            memcpy(w->htable, htable, 8192);
            uint32_t ctr = ctr0 + 1 + (uint32_t)off;
            memcpy(w->iv, J0, 12);
            w->iv[12] = ctr >> 24; w->iv[13] = ctr >> 16; w->iv[14] = ctr >> 8; w->iv[15] = ctr;
        }
        g_pool.phase = g_pool.phase ^ 1; /* 0<->1, never 2 */
        if (g_pool.phase == 2) g_pool.phase = 0;
        /* phase must differ from seen. seen starts 0. We toggle 0 and 1. */
        pthread_cond_broadcast(&g_pool.cv);
        while (g_pool.remaining) pthread_cond_wait(&g_pool.cv, &g_pool.mtx);
        pthread_mutex_unlock(&g_pool.mtx);
    }

    if (rem) {
        unsigned char ks[16], ctrb[16];
        memcpy(ctrb, J0, 12);
        uint32_t ctr = ((uint32_t)J0[12] << 24) | ((uint32_t)J0[13] << 16) |
                       ((uint32_t)J0[14] << 8) | J0[15];
        ctr = ctr + 1 + (uint32_t)blocks;
        ctrb[12] = ctr >> 24; ctrb[13] = ctr >> 16; ctrb[14] = ctr >> 8; ctrb[15] = ctr;
        aesni_encrypt(ctrb, ks, aeskey);
        for (size_t i = 0; i < rem; i++) out[blocks * 16 + i] = pt[blocks * 16 + i] ^ ks[i];
    }

    /* Single-thread GHASH over AAD || CT || lengths. For large CT this is the remaining cost.
       If parallel, combine chunk Xi. */
    unsigned char Xi[16];
    memset(Xi, 0, 16);
    if (aad_len) {
        size_t n = aad_len & ~15ULL;
        if (n) gcm_ghash_avx(Xi, htable, aad, n);
        if (aad_len & 15) {
            unsigned char blk[16] = {0};
            memcpy(blk, aad + n, aad_len - n);
            gcm_ghash_avx(Xi, htable, blk, 16);
        }
    }

    if (nt == 1) {
        size_t n = pt_len & ~15ULL;
        if (n) gcm_ghash_avx(Xi, htable, out, n);
        if (rem) {
            unsigned char blk[16] = {0};
            memcpy(blk, out + n, rem);
            gcm_ghash_avx(Xi, htable, blk, 16);
        }
    } else {
        /* Build H^{2^i} */
        unsigned char pows[MAX_POW][16];
        memcpy(pows[0], H, 16);
        unsigned char cur[16];
        memcpy(cur, H, 16);
        unsigned char table[1024];
        size_t maxexp = blocks + 4;
        int nbits = 0;
        while ((1ULL << nbits) <= maxexp && nbits < MAX_POW - 1) nbits++;
        for (int i = 0; i < nbits; i++) {
            mul(cur, cur, table); /* square: wait, mul(cur, cur) uses cur as both and overwrites. Need copy. */
        }
        /* redo properly */
        memcpy(cur, H, 16);
        for (int i = 0; i < nbits; i++) {
            unsigned char y[16];
            memcpy(y, cur, 16);
            mul(cur, y, table);
            memcpy(pows[i + 1], cur, 16);
        }
        /* pows[0]=H^1, pows[i]=H^{2^i} */
        unsigned char acc[16] = {0};
        size_t ct_blocks = blocks + (rem ? 1 : 0);
        for (int i = 0; i < nt; i++) {
            size_t off = g_pool.w[i].off_blocks;
            size_t n = g_pool.w[i].blocks;
            size_t after = blocks - (off + n);
            size_t sh = after + (rem ? 1 : 0);
            unsigned char buf[16];
            memcpy(buf, g_pool.w[i].xi, 16);
            size_t e = sh;
            int bit = 0;
            while (e) {
                if (e & 1) mul(buf, pows[bit], table);
                e >>= 1; bit++;
            }
            xor16(acc, buf);
        }
        if (rem) {
            unsigned char blk[16] = {0}, tmp[16] = {0};
            memcpy(blk, out + blocks * 16, rem);
            gcm_ghash_avx(tmp, htable, blk, 16);
            xor16(acc, tmp);
        }
        /* Xi = AAD_state * H^{ct_blocks} xor acc */
        if (ct_blocks) {
            size_t e = ct_blocks;
            int bit = 0;
            while (e) {
                if (e & 1) mul(Xi, pows[bit], table);
                e >>= 1; bit++;
            }
        }
        xor16(Xi, acc);
    }

    unsigned char lens[16] = {0};
    uint64_t ab = (uint64_t)aad_len * 8, cb = (uint64_t)pt_len * 8;
    for (int i = 0; i < 8; i++) {
        lens[7 - i] = (unsigned char)(ab >> (8 * i));
        lens[15 - i] = (unsigned char)(cb >> (8 * i));
    }
    gcm_ghash_avx(Xi, htable, lens, 16);

    unsigned char EK[16];
    aesni_encrypt(J0, EK, aeskey);
    for (int i = 0; i < 16; i++) tag[i] = Xi[i] ^ EK[i];
    return 0;
}
