/* Parallel AES-GCM via OpenSSL's aesni_gcm_encrypt (AES-NI + PCLMUL, 6-block stride).
 * Chunks are independent CTR streams; GHASH is done once over the ciphertext.
 *
 * cc -O3 -shared -fPIC -o aesgcm_fast.so aesgcm_fast.c -L/usr/local/lib -lcrypto -lpthread
 */
#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

extern size_t aesni_gcm_encrypt(const unsigned char *in, unsigned char *out, size_t len,
                                const void *key, unsigned char ivec[16], void *Htable);
extern int aesni_set_encrypt_key(const unsigned char *userKey, int bits, void *key);
extern void aesni_encrypt(const unsigned char *in, unsigned char *out, const void *key);
extern void gcm_init_avx(void *Htable, const void *H);
extern void gcm_init_clmul(void *Htable, const void *H);
extern void gcm_ghash_avx(void *Xi, const void *Htable, const unsigned char *inp, size_t len);
extern void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
                                       size_t blocks, const void *key, const unsigned char ivec[16]);

static void bswap64_16(const unsigned char in[16], unsigned char out[16]) {
    for (int i = 0; i < 8; i++) {
        out[i] = in[7 - i];
        out[8 + i] = in[15 - i];
    }
}

#define MAX_T 6

typedef struct {
    const unsigned char *in;
    unsigned char *out;
    size_t off, len;
    const unsigned char *key;
    unsigned char *htable;
    unsigned char iv[16];
    atomic_int *go;
    atomic_int *done_count;
    int stop;
} job_t;

static job_t jobs[MAX_T];
static pthread_t threads[MAX_T];
static atomic_int go_flag;
static atomic_int done_count;
static int nthreads_live = 0;

static void *worker(void *arg) {
    job_t *j = arg;
    int seen = 0;
    for (;;) {
        int g;
        while ((g = atomic_load(&go_flag)) == seen) {
            /* spin */
        }
        seen = g;
        if (j->stop) return NULL;
        if (j->len) {
            aesni_gcm_encrypt(j->in + j->off, j->out + j->off, j->len, j->key, j->iv, j->htable);
        }
        atomic_fetch_add(&done_count, 1);
    }
}

static void ensure_threads(int nt) {
    if (nthreads_live >= nt) return;
    for (int i = nthreads_live; i < nt; i++) {
        jobs[i].stop = 0;
        pthread_create(&threads[i], NULL, worker, &jobs[i]);
    }
    nthreads_live = nt;
}

int aesgcm_encrypt(const unsigned char *key, int key_bits,
                   const unsigned char *nonce, size_t nonce_len,
                   const unsigned char *aad, size_t aad_len,
                   const unsigned char *pt, size_t pt_len,
                   unsigned char *out, unsigned char tag[16],
                   int nthreads) {
    unsigned char aeskey[256];
    if (aesni_set_encrypt_key(key, key_bits, aeskey) != 0) return -1;

    unsigned char H[16], zero[16] = {0};
    aesni_encrypt(zero, H, aeskey);
    unsigned char Hs[16];
    bswap64_16(H, Hs);

    /* clmul table is what aesni_gcm_encrypt consumes; avx table is for gcm_ghash_avx */
    unsigned char htable_clmul[4096];
    unsigned char htable_avx[8192];
    gcm_init_clmul(htable_clmul, H);          /* aesni_gcm_encrypt expects raw H (it bswaps internally) */
    gcm_init_avx(htable_avx, Hs);             /* ghash wants 64-bit swapped H */

    unsigned char J0[16];
    if (nonce_len == 12) {
        memcpy(J0, nonce, 12);
        J0[12] = 0; J0[13] = 0; J0[14] = 0; J0[15] = 1;
    } else {
        memset(J0, 0, 16);
        size_t n = nonce_len & ~15ULL;
        if (n) gcm_ghash_avx(J0, htable_avx, nonce, n);
        if (nonce_len & 15) {
            unsigned char blk[16] = {0};
            memcpy(blk, nonce + n, nonce_len - n);
            gcm_ghash_avx(J0, htable_avx, blk, 16);
        }
        unsigned char lens[16] = {0};
        uint64_t bits = (uint64_t)nonce_len * 8;
        for (int i = 0; i < 8; i++) lens[15 - i] = (unsigned char)(bits >> (8 * i));
        gcm_ghash_avx(J0, htable_avx, lens, 16);
    }

    uint32_t ctr0 = ((uint32_t)J0[12] << 24) | ((uint32_t)J0[13] << 16) |
                    ((uint32_t)J0[14] << 8) | (uint32_t)J0[15];

    size_t blocks = pt_len >> 4;
    size_t rem = pt_len & 15;

    int nt = nthreads;
    if (nt < 1) nt = 1;
    if (nt > MAX_T) nt = MAX_T;
    /* fused kernel needs >= 0x120 bytes and is happiest on big chunks */
    if (pt_len < 256 * 1024) nt = 1;

    if (nt == 1) {
        if (pt_len) {
            unsigned char iv[16];
            memcpy(iv, J0, 12);
            uint32_t ctr = ctr0 + 1;
            iv[12] = ctr >> 24; iv[13] = ctr >> 16; iv[14] = ctr >> 8; iv[15] = ctr;
            size_t done = aesni_gcm_encrypt(pt, out, pt_len, aeskey, iv, htable_clmul);
            if (done < pt_len) {
                /* tail via CTR */
                size_t tail_blocks = (pt_len - done) >> 4;
                size_t tail_rem = (pt_len - done) & 15;
