#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <pthread.h>
#include <stdlib.h>

extern size_t aesni_gcm_encrypt(const unsigned char *in, unsigned char *out, size_t len,
                                const void *key, unsigned char ivec[16], void *Htable);
extern int aesni_set_encrypt_key(const unsigned char *userKey, int bits, void *key);
extern void aesni_encrypt(const unsigned char *in, unsigned char *out, const void *key);
extern void gcm_init_clmul(void *Htable, const void *H);
extern void gcm_init_avx(void *Htable, const void *H);
extern void gcm_ghash_avx(void *Xi, const void *Htable, const unsigned char *inp, size_t len);
extern void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
                                       size_t blocks, const void *key, const unsigned char ivec[16]);

static void bswap64_16(const unsigned char in[16], unsigned char out[16]) {
    for (int i = 0; i < 8; i++) {
        out[i] = in[7 - i];
        out[8 + i] = in[15 - i];
    }
}

#define MAX_T 4

typedef struct {
    const unsigned char *pt;
    unsigned char *out;
    const unsigned char *aeskey;
    unsigned char *ht_clmul;   /* source, copied per chunk */
    unsigned char *ht_avx;
    size_t off_blocks, nblocks;
    unsigned char iv_prefix[12];
    uint32_t ctr0;
    unsigned char xi[16];
    pthread_mutex_t *mtx;
    pthread_cond_t *cv;
    int *phase;
    int *remaining;
    int stop;
} job_t;

static void do_job(job_t *j) {
    if (!j->nblocks) {
        memset(j->xi, 0, 16);
        return;
    }
    unsigned char ht[4096];
    memcpy(ht, j->ht_clmul, 4096);
    unsigned char iv[16];
    memcpy(iv, j->iv_prefix, 12);
    uint32_t ctr = j->ctr0 + 1 + (uint32_t)j->off_blocks;
    iv[12] = ctr >> 24; iv[13] = ctr >> 16; iv[14] = ctr >> 8; iv[15] = ctr;
    size_t nbytes = j->nblocks * 16;
    size_t done = aesni_gcm_encrypt(j->pt + j->off_blocks * 16,
                                    j->out + j->off_blocks * 16,
                                    nbytes, j->aeskey, iv, ht);
    if (done < nbytes) {
        uint32_t c = j->ctr0 + 1 + (uint32_t)j->off_blocks + (uint32_t)(done >> 4);
        memcpy(iv, j->iv_prefix, 12);
        iv[12] = c >> 24; iv[13] = c >> 16; iv[14] = c >> 8; iv[15] = c;
        aesni_ctr32_encrypt_blocks(j->pt + j->off_blocks * 16 + done,
                                   j->out + j->off_blocks * 16 + done,
                                   (nbytes - done) >> 4, j->aeskey, iv);
    }
    memset(j->xi, 0, 16);
    gcm_ghash_avx(j->xi, j->ht_avx, j->out + j->off_blocks * 16, nbytes);
}

static void *worker(void *arg) {
    job_t *j = arg;
    int seen = 0;
    for (;;) {
        pthread_mutex_lock(j->mtx);
        while (*j->phase == seen) pthread_cond_wait(j->cv, j->mtx);
        seen = *j->phase;
        int stop = j->stop;
        pthread_mutex_unlock(j->mtx);
        if (stop) return NULL;
        do_job(j);
        pthread_mutex_lock(j->mtx);
        if (--*j->remaining == 0) pthread_cond_signal(j->cv);
        pthread_mutex_unlock(j->mtx);
    }
}

typedef struct {
    pthread_t th[MAX_T];
    job_t jobs[MAX_T];
    pthread_mutex_t mtx;
    pthread_cond_t cv;
    int phase;
    int remaining;
    int live;
} pool_t;

static pool_t pool;

static void pool_init(int nt) {
    if (pool.live) return;
    pthread_mutex_init(&pool.mtx, NULL);
    pthread_cond_init(&pool.cv, NULL);
    pool.phase = 0;
    for (int i = 0; i < nt; i++) {
        pool.jobs[i].mtx = &pool.mtx;
        pool.jobs[i].cv = &pool.cv;
        pool.jobs[i].phase = &pool.phase;
        pool.jobs[i].remaining = &pool.remaining;
        pool.jobs[i].stop = 0;
        pthread_create(&pool.th[i], NULL, worker, &pool.jobs[i]);
    }
    pool.live = nt;
}

/* Returns 0. Writes ciphertext to out (pt_len bytes) and per-chunk GHASH to xis (nt*16).
 * Also writes H (16) and J0 (16) for the caller to finish the tag.
 * nt_io: in: desired threads, out: threads used.
 */
int aes_bulk(const unsigned char *key, int key_bits,
             const unsigned char *nonce, size_t nonce_len,
             const unsigned char *pt, size_t pt_len,
             unsigned char *out,
             unsigned char H_out[16],
             unsigned char J0_out[16],
             unsigned char *xis,          /* nt * 16 */
             size_t *offs,                /* nt block offsets */
             size_t *lens,                /* nt block counts */
             int *nt_io) {
    unsigned char aeskey[256];
    if (aesni_set_encrypt_key(key, key_bits, aeskey)) return -1;
    unsigned char H[16], zero[16] = {0};
    aesni_encrypt(zero, H, aeskey);
    memcpy(H_out, H, 16);
    unsigned char Hs[16];
    bswap64_16(H, Hs);
    unsigned char ht_clmul[4096];
    unsigned char ht_avx[8192];
    gcm_init_clmul(ht_clmul, H);
    gcm_init_avx(ht_avx, Hs);

    unsigned char J0[16];
    if (nonce_len == 12) {
        memcpy(J0, nonce, 12);
        J0[12] = 0; J0[13] = 0; J0[14] = 0; J0[15] = 1;
    } else {
        memset(J0, 0, 16);
        size_t n = nonce_len & ~15ULL;
        if (n) gcm_ghash_avx(J0, ht_avx, nonce, n);
        if (nonce_len & 15) {
            unsigned char blk[16] = {0};
            memcpy(blk, nonce + n, nonce_len - n);
            gcm_ghash_avx(J0, ht_avx, blk, 16);
        }
        unsigned char lensb[16] = {0};
        uint64_t bits = (uint64_t)nonce_len * 8;
        for (int i = 0; i < 8; i++) lensb[15 - i] = (unsigned char)(bits >> (8 * i));
        gcm_ghash_avx(J0, ht_avx, lensb, 16);
    }
    memcpy(J0_out, J0, 16);
    uint32_t ctr0 = ((uint32_t)J0[12] << 24) | ((uint32_t)J0[13] << 16) |
                    ((uint32_t)J0[14] << 8) | J0[15];

    size_t blocks = pt_len >> 4;
    size_t rem = pt_len & 15;
    int nt = *nt_io;
    if (nt < 1) nt = 1;
    if (nt > MAX_T) nt = MAX_T;
    if (blocks < 8192) nt = 1;
    *nt_io = nt;

    if (nt == 1) {
        job_t j;
        memset(&j, 0, sizeof j);
        j.pt = pt; j.out = out; j.aeskey = aeskey;
        j.ht_clmul = ht_clmul; j.ht_avx = ht_avx;
        j.off_blocks = 0; j.nblocks = blocks;
        memcpy(j.iv_prefix, J0, 12);
        j.ctr0 = ctr0;
        do_job(&j);
        memcpy(xis, j.xi, 16);
        offs[0] = 0; lens[0] = blocks;
    } else {
        pool_init(nt);
        size_t chunk = blocks / nt;
        pthread_mutex_lock(&pool.mtx);
        pool.remaining = nt;
        size_t off = 0;
        for (int i = 0; i < nt; i++) {
            size_t n = (i == nt - 1) ? blocks - off : chunk;
            job_t *j = &pool.jobs[i];
            j->pt = pt; j->out = out; j->aeskey = aeskey;
            j->ht_clmul = ht_clmul; j->ht_avx = ht_avx;
            j->off_blocks = off; j->nblocks = n;
            memcpy(j->iv_prefix, J0, 12);
            j->ctr0 = ctr0;
            j->stop = 0;
            offs[i] = off; lens[i] = n;
            off += n;
        }
        pool.phase++;
        pthread_cond_broadcast(&pool.cv);
        while (pool.remaining) pthread_cond_wait(&pool.cv, &pool.mtx);
        pthread_mutex_unlock(&pool.mtx);
        for (int i = 0; i < nt; i++) memcpy(xis + i * 16, pool.jobs[i].xi, 16);
    }
    if (rem) {
        unsigned char ks[16], ctrb[16];
        memcpy(ctrb, J0, 12);
        uint32_t c = ctr0 + 1 + (uint32_t)blocks;
        ctrb[12] = c >> 24; ctrb[13] = c >> 16; ctrb[14] = c >> 8; ctrb[15] = c;
        aesni_encrypt(ctrb, ks, aeskey);
        for (size_t i = 0; i < rem; i++) out[blocks * 16 + i] = pt[blocks * 16 + i] ^ ks[i];
    }
    return 0;
}
