                                const void *key, unsigned char ivec[16], void *Htable);
extern int aesni_set_encrypt_key(const unsigned char *userKey, int bits, void *key);
extern void aesni_encrypt(const unsigned char *in, unsigned char *out, const void *key);
extern void gcm_init_clmul(void *Htable, const void *H);
extern void gcm_init_avx(void *Htable, const void *H);
extern void gcm_ghash_avx(void *Xi, const void *Htable, const unsigned char *inp, size_t len);
extern void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
                                       size_t blocks, const void *key, const unsigned char ivec[16]);

#define MAX_T 4

typedef struct {
    const unsigned char *pt;
    unsigned char *out;
    const unsigned char *aeskey;
    const unsigned char *ht_clmul;
    const unsigned char *ht_avx;
    size_t off, n;          /* bytes, multiple of 16 */
    unsigned char iv[16];
    unsigned char xi[16];
    atomic_int *go;
    atomic_int *done;
    int stop;
    unsigned char ht_local[4096];
} job_t;

static job_t jobs[MAX_T];
static pthread_t ths[MAX_T];
static atomic_int go_flag, done_count;
static int live = 0;

static void work(job_t *j) {
    if (!j->n) { memset(j->xi, 0, 16); return; }
    memcpy(j->ht_local, j->ht_clmul, 4096);
    size_t done = aesni_gcm_encrypt(j->pt + j->off, j->out + j->off, j->n, j->aeskey, j->iv, j->ht_local);
    if (done < j->n) {
        /* advance counter by done/16. iv counter is last 4 bytes big-endian */
        uint32_t c = ((uint32_t)j->iv[12] << 24) | ((uint32_t)j->iv[13] << 16) |
                     ((uint32_t)j->iv[14] << 8) | j->iv[15];
        c += (uint32_t)(done >> 4);
        unsigned char iv2[16];
        memcpy(iv2, j->iv, 12);
        iv2[12] = c >> 24; iv2[13] = c >> 16; iv2[14] = c >> 8; iv2[15] = c;
        aesni_ctr32_encrypt_blocks(j->pt + j->off + done, j->out + j->off + done,
                                   (j->n - done) >> 4, j->aeskey, iv2);
    }
    memset(j->xi, 0, 16);
    gcm_ghash_avx(j->xi, (void *)j->ht_avx, j->out + j->off, j->n);
}

static void *worker(void *arg) {
    job_t *j = arg;
    int seen = 0;
    for (;;) {
        int g;
        while ((g = atomic_load_explicit(&go_flag, memory_order_acquire)) == seen) ;
        seen = g;
        if (j->stop) return NULL;
        work(j);
        atomic_fetch_add_explicit(&done, memory_order_release);
    }
    return NULL;
}

/* fix: done is a pointer */
static void *worker2(void *arg) {
    job_t *j = arg;
    int seen = 0;
    for (;;) {
        int g;
        while ((g = atomic_load_explicit(j->go, memory_order_acquire)) == seen) ;
        seen = g;
        if (j->stop) return NULL;
        work(j);
        atomic_fetch_add_explicit(j->done, 1, memory_order_release);
    }
    return NULL;
}

static void ensure(int nt) {
    if (live) return;
    for (int i = 0; i < nt; i++) {
        jobs[i].go = &go_flag;
        jobs[i].done = &done_count;
        jobs[i].stop = 0;
        pthread_create(&ths[i], NULL, worker2, &jobs[i]);
    }
    live = nt;
}

int aes_bulk(const unsigned char *key, int key_bits,
             const unsigned char *nonce, size_t nonce_len,
             const unsigned char *pt, size_t pt_len,
             unsigned char *out,
             int nt) {
    unsigned char aeskey[256];
    if (aesni_set_encrypt_key(key, key_bits, aeskey)) return -1;
    unsigned char H[16] = {0}, z[16] = {0};
    aesni_encrypt(z, H, aeskey);
    unsigned char ht_clmul[4096];
    gcm_init_clmul(ht_clmul, H);
    unsigned char Hs[16];
    for (int i = 0; i < 8; i++) { Hs[i] = H[7 - i]; Hs[8 + i] = H[15 - i]; }
    unsigned char ht_avx[8192];
    gcm_init_avx(ht_avx, Hs);

    if (nonce_len != 12) return -2;
    size_t blocks = pt_len >> 4;
    if (nt < 1) nt = 1;
    if (nt > MAX_T) nt = MAX_T;
    if (blocks < 4096) nt = 1;

    if (nt == 1) {
        job_t j;
        memset(&j, 0, sizeof j);
        j.pt = pt; j.out = out; j.aeskey = aeskey;
        j.ht_clmul = ht_clmul; j.ht_avx = ht_avx;
        j.off = 0; j.n = blocks * 16;
        memcpy(j.iv, nonce, 12);
        j.iv[15] = 2;
        work(&j);
    } else {
        ensure(nt);
        size_t chunk = (blocks / nt) * 16;
        for (int i = 0; i < nt; i++) {
            size_t off = (size_t)i * chunk;
            size_t n = (i == nt - 1) ? (blocks * 16 - off) : chunk;
            jobs[i].pt = pt; jobs[i].out = out; jobs[i].aeskey = aeskey;
            jobs[i].ht_clmul = ht_clmul; jobs[i].ht_avx = ht_avx;
            jobs[i].off = off; jobs[i].n = n;
            memcpy(jobs[i].iv, nonce, 12);
            uint32_t ctr = 2 + (uint32_t)(off >> 4);
            jobs[i].iv[12] = ctr >> 24; jobs[i].iv[13] = ctr >> 16;
            jobs[i].iv[14] = ctr >> 8; jobs[i].iv[15] = ctr;
            jobs[i].stop = 0;
        }
        atomic_store_explicit(&done_count, 0, memory_order_relaxed);
        atomic_fetch_add_explicit(&go_flag, 1, memory_order_release);
        while (atomic_load_explicit(&done_count, memory_order_acquire) < nt) ;
    }
    size_t rem = pt_len & 15;
    if (rem) {
        unsigned char ks[16], iv[16];
        memcpy(iv, nonce, 12);
        uint32_t c = 2 + (uint32_t)blocks;
        iv[12] = c >> 24; iv[13] = c >> 16; iv[14] = c >> 8; iv[15] = c;
        aesni_encrypt(iv, ks, aeskey);
        for (size_t i = 0; i < rem; i++) out[blocks * 16 + i] = pt[blocks * 16 + i] ^ ks[i];
    }
    return 0;
}
