#include <stdint.h>
#include <stddef.h>
#include <string.h>

extern size_t aesni_gcm_encrypt(const unsigned char *in, unsigned char *out, size_t len,
                                const void *key, unsigned char ivec[16], void *Htable);
extern void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
                                       size_t blocks, const void *key, const unsigned char ivec[16]);
extern void gcm_ghash_avx(void *Xi, const void *Htable, const unsigned char *inp, size_t len);

/* Encrypt n bytes (multiple of 16) at pt[off] into out[off] with the given 16-byte IV
 * (counter for the first block) and AES-NI key. Copies clmul table (which the kernel mutates)
 * from ht_clmul. Then GHASH the ciphertext into xi (16 bytes, must be zeroed by caller or we zero it).
 */
size_t aes_chunk(const unsigned char *pt, unsigned char *out, size_t off, size_t n,
                 const unsigned char *aeskey, unsigned char iv[16],
                 const unsigned char *ht_clmul, const unsigned char *ht_avx,
                 unsigned char xi[16]) {
    unsigned char ht[4096];
    memcpy(ht, ht_clmul, 4096);
    size_t done = 0;
    if (n) {
        done = aesni_gcm_encrypt(pt + off, out + off, n, aeskey, iv, ht);
        if (done < n) {
            uint32_t c = ((uint32_t)iv[12] << 24) | ((uint32_t)iv[13] << 16) |
                         ((uint32_t)iv[14] << 8) | iv[15];
            /* aesni_gcm_encrypt advances iv by the blocks it processed */
            unsigned char iv2[16];
            memcpy(iv2, iv, 16);
            aesni_ctr32_encrypt_blocks(pt + off + done, out + off + done, (n - done) >> 4, aeskey, iv2);
        }
    }
    if (xi && ht_avx && n) {
        memset(xi, 0, 16);
        gcm_ghash_avx(xi, (void *)ht_avx, out + off, n);
    }
    return done;
}
