class W(threading.Thread):
    def __init__(self):
        super().__init__(daemon=True)
        self.req=threading.Event(); self.ack=threading.Event(); self.fn=None
        self.start()
    def run(self):
        while True:
            self.req.wait(); self.req.clear()
            if self.fn is None: return
            self.fn(); self.ack.set()
    def call(self, fn):
        self.ack.clear(); self.fn=fn; self.req.set()
    def wait(self):
        self.ack.wait()
